!function(){const t=document.getElementById("testiTrack"),e=document.querySelectorAll(".testi-dot");let n=0;const c=e.length;function s(s){n=(s+c)%c,t.style.transform=`translateX(-${100*n}%)`,e.forEach((t,e)=>t.classList.toggle("active",e===n))}document.getElementById("testiNext").addEventListener("click",()=>s(n+1)),document.getElementById("testiPrev").addEventListener("click",()=>s(n-1)),e.forEach(t=>t.addEventListener("click",()=>s(+t.dataset.idx))),setInterval(()=>s(n+1),5e3)}();